 "content": "def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        # A horizontal color bar ends at its first non-bar cell; mark that endpoint.
        colors = [c for c in set(row) if row.count(c) > 1]
        if not colors:
            continue
        color = max(colors, key=row.count)
        inds = [i for i, v in enumerate(row) if v == color]
        if inds == list(range(inds[0], inds[-1] + 1)):
            if inds[-1] == len(row) - 1:
                continue
            # The bar runs from the left edge and has a single anomalous final cell,
            # or terminates before the right edge; mark the first cell beyond it.
            nxt = inds[-1] + 1
            if nxt == len(row) - 1 or row[nxt] != color:
                out[r][nxt] = 1
    return out
"
}

